import type { Element } from './elements';
import { POKEDEX_SPECIES } from '../content/pokedex';
import { axisOf, type MeasureAxis } from './shapes';
import { defaultRules } from './defaults';
import { defaultRole } from './roles';

// Species model. The survivor game's roster is the Pokémon in src/content/pokedex.ts,
// generated by scripts/build-content.mjs from PokéAPI (data), PMD SpriteCollab (sprites,
// portraits) and PokeAPI/cries, with gameplay roles from content/roster.json.

export interface Stats { hp: number; atk: number; def: number; spa: number; spd: number; spe: number }

type BossAttack = 'charge' | 'slam' | 'radial' | 'spiral' | 'summon' | 'volley' | 'boulder';
export type Behaviour = 'chase' | 'ranged' | 'charger' | 'swarm' | 'healer' | 'tank';

export interface SpeciesDef {
  id: string;
  name: string;
  elements: Element[];
  stats: Stats;
  height: number; // world height of the sprite (m)
  flying?: boolean; // glide (player) / float over terrain (enemy)
  art: string;
  dex?: number; // national Pokédex number
  types?: string[]; // official type names, for display
  scale?: number; // integer sprite scale (bosses are drawn 2-4x)
  // player-only
  playable?: boolean;
  blurb?: string;
  starter?: string; // starting move key
  learnset?: [number, string][]; // [game level, moveKey] (curated in content/roster.json)
  /** the line's other canonical level-up attacks [canonical level, key], offered rarely as coverage */
  coverage?: [number, string][];
  evolvesTo?: string;
  evolveLevel?: number; // game evolution level
  /** cross-game source facts, kept apart from Poke-Watch balancing */
  canon?: {
    levelUp: [number, string][]; abilities: string[]; heightM: number; weightKg: number; evolveLevel?: number; evolveTrigger?: string;
    /** canonical level-up moves with no game move row (most status moves, one-hit KOs): read by the default role rule */
    levelUpOther?: string[];
    /** the pinned snapshot flags the species legendary or mythical (an `everyWild` pool leaves it out by default) */
    special?: 'legendary' | 'mythical';
    /** official body shape (PokéAPI `pokemon_shapes` identifier), from the pinned CSV snapshot */
    shape?: string;
    /** what `heightM` measures: SPECIES_AXIS, else `shape` through SHAPE_AXIS (src/rules/shapes.ts); set when the roster loads */
    axis?: MeasureAxis;
  };
  ability?: string; // legacy originals only ('adaptive'); Pokémon abilities come from canon.abilities
  // enemy-only
  /** a wild roster entry (content/roster.json `wild`), whether or not it names its role */
  wild?: boolean;
  /** the roster wave it joined with (content/roster.json; data only since the spawn pools were deleted) */
  wave?: string;
  /** `rule`: behaviour and flight came from the default role rule (src/rules/roles.ts), not the roster entry */
  roleFrom?: 'rule';
  behaviour?: Behaviour;
  shot?: Element; // ranged projectile element
  boss?: { attacks: BossAttack[]; phaseHp: number[]; summon?: string; title: string };
}

export const SPECIES: SpeciesDef[] = POKEDEX_SPECIES;
// the measurement axis is rules data (src/rules/shapes.ts), not generated content: derive it once from the shape
for (const s of SPECIES) if (s.canon) s.canon.axis = axisOf(s.id, s.canon.shape);
// a wild entry that names no behaviour takes the default role rule (src/rules/roles.ts); a `flying` it sets wins. Read
// once from the default rules (rules.wildRole), like the axis above: every reader then sees one role per species
for (const s of SPECIES) {
  if (!s.wild || s.behaviour !== undefined) continue;
  const role = defaultRole(s, defaultRules);
  s.behaviour = role.behaviour;
  if (s.flying === undefined && role.flying) s.flying = true;
  s.roleFrom = 'rule';
}

export const SPECIES_BY_ID: Record<string, SpeciesDef> = Object.fromEntries(SPECIES.map((s) => [s.id, s]));

/** A starter-eligible pool should prefer one option per evolutionary line and avoid repeat families. */
function starterFamilyRoot(sp: SpeciesDef): SpeciesDef {
  let root = sp;
  while (root.evolvesTo) {
    const previous = SPECIES.find((candidate) => candidate.evolvesTo === root.id);
    if (!previous) break;
    root = previous;
  }
  return root;
}

export function starterEligibleSpecies(): SpeciesDef[] {
  const seen = new Set<string>();
  const out: SpeciesDef[] = [];
  for (const sp of SPECIES.filter((s) => s.playable)) {
    const root = starterFamilyRoot(sp);
    if (seen.has(root.id)) continue;
    seen.add(root.id);
    out.push(sp);
  }
  return out;
}

/** Weight class 0-4 from PokéAPI kilograms: Weightless < 1 kg, Light < 10, Medium < 50, Heavy < 200, Massive.
 *  It decides what a Pokémon can Guard against and what can move it. */
export function weightClass(sp: SpeciesDef): number {
  const kg = sp.canon?.weightKg ?? 20;
  return kg < 1 ? 0 : kg < 10 ? 1 : kg < 50 ? 2 : kg < 200 ? 3 : 4;
}
export const WEIGHT_NAMES = ['Weightless', 'Light', 'Medium', 'Heavy', 'Massive'] as const;
